      '**紧急任务·雷厉 BOSS**(图2-6)：杨歧施放 ≥3 次「炼狱天罡」。BOSS 机制：① 炼狱天罡 —— **前排怪全存活时才会使用**，减少我方全体单位 1/4 的最大气血；② 鬼蜮勾魂 —— 前排有怪倒地时才会用，对我方单个单位「勾魂」；③ 渡魂入体 —— 使用「鬼蜮勾魂」后，立即对倒地的「魔化村民」使用，使其满血复活。我方雷厉：当后排怪（主除外）被击飞后，会使用大招掉刷前排怪。杀法1（扛不住时，适当 JQ、LH）：适当封印后排，用「前后交替」杀法（杀 1 个前排输出后，分配输出到守该单位的尸体，同时击杀后排），直至剩 1 个后排小怪时再完成紧急。杀法2（扛得住，适当 JQ、LH）：① 封后排「法系」杀后排「物理」→ ② 封 1 个后排「封辅」，杀另 1 个后排「封辅」→ ③ 杀后排「法系」（可无魂前排）→ ④ 紧急完成后「前后交替」杀法 → ⑤ 后排怪全击飞后防御即可（若有倒地地单位、则拉起来）。**也可先扫 3 个大招、完成紧急后逃跑，再按「前后交替」杀法击杀（紧急已完成、鬼蜮入体又无用）—— 可惜魔化村民复生，大家小心！**',
