      '**乔商捉迷藏**(图2-4)：附近逐渐扩大范围找，参考坐标 296,321 / 243,289 / 329,279 / 278,326 / 243,289（坡）。捉迷藏 E 后：E-1 选真心话（乔 +5）/ E-2 选大冒险（乔 +2）。',
      '**填填乐**(图2-5)：横行词提示信息 —— ① 点击空白处获得提示 → ② 根据提示（如「3 级药品、名贵药物、精心炼制的丹药，可用于补充些许灵力」）填入「定」「神」得「定神香」→ ③ 在空白处输入 →④ 以此类推、输入另一个药品 → ⑤ 点「答完了」完成小游戏。',
      '**紧急任务·目光如炬**（诡秘黑影，图2-6）：3 回合内击败诡秘黑影。主怪血较高、小怪略高。第 1 回合主分身术、DF 尸腐毒/黄泉之息、DT 平砍；第 2 回合 DF 锢魂符+摄魂、DT 横扫人物（防最低的）；第 4 回合会跑，紧急任务失败。杀法：封足够快就直接封主、其余单位点主杀；封不中/不够快就每回合破分身、其余单位杀主，抗性不足可以封 1 个 DT；小怪逐一击杀即可。',
      '**紧急任务·五音不全**（黑衣人第三场，图2-7）：4 回合内击破宫、商、角、徵、羽。小怪都会神迹。后排 NE 第一回合会「青烟袅袅」，秒 7~8 个单位、所有命中单位都会中毒 1 回合，下回合会减少中毒者较多气血（约最大生命值的 10%）。杀法：① 集火 1 个法系、封后排 1~2 个 NE → ② 集火另 1 个法系，第 2 回合若有「毒」状态建议回复直接回血、必要时 LH → ③ 逐一击杀。',
      '**第四场 O/P 二选一**（拦周幽 图2-8 / 拦云裳 图2-9，紧急任务「金刚玉骨：没有玩家在战斗中倒地」）：拦周幽 —— 主血较高、小怪 <4 个下回合补满 4 个、被击飞会自爆（被封则无法自爆），集火杀主至死、逐一杀小怪（3X 时可适当封印、注意血量防带走）；拦云裳 —— 所有怪被击飞都会「死亡之音」（被封特技后无法释放），封天将特技、物理杀天将、法系杀羽灵神（**建议别群秒**）。',
      '**紧急任务·真假难辨**（周幽第五场，图2-9）：第一回合内将周幽和吕思的气血降到 35%。周大虎和吕小娘「生命链接」，是群秒伤害不叠加；第 3 回合周大虎和吕小娘会变成「幻术傀儡」（屠气妖），同时再各分身 2 个「幻术傀儡」，被封则无法分身；周幽、吕思回合 ≥2 时无敌状态取消。杀法：① 前 3 回合单体技能、封杀周大虎、吕小娘 → ② 第 4 回合合理分配输出杀吕思、周幽（如对位等）。',
