      '**紧急任务·剑胆琴心**（吴天兵第七场 BOSS，图2-11）：竭尽全力、击破吴天兵。前排屐气妖抗性一般，约 1W5 血（175 级），每 2 回合变换一次：悲、思、恨（难度 ≥3X 死亡后有不同效果：悲 = 善恶有报无实效、思 = 上古灵符、恨 = 壁垒击破）；PS 第 2 回合会「死亡召唤」血最少的单位；主怪前排屐气妖越少抗性越低（上 1 回合若无屐气妖，下 1 回合即有 4 个屐气妖、主怪无抗性）；琴仙无敌状态、与主怪「生命链接」、对应前面的屐气妖死后会变为 BY 且伤害减半；主前第 3、6…… 回合会变换造型并可能出现屐气妖，主死的下一回合无敌状态才消失。杀法：① 对位点屐气妖，当屐气妖数量剩 1~2 个时高速连续杀屐气妖、其余单体技能杀主 → ② 当场上站满屐气妖后，循环第①步即可。',
