      '**紧急任务·固若金汤**（凌雨露，图2-6）：队伍中没有人死亡。怪物第一回合基本破血 BB，第二回合才用技能杀玩家。杀法（注意 JQ 及时解毒）：封「物理」杀没被封的「物理」→ 逐一杀即可（或：第 1 回合 BB 防，第 2 回合抗性低的玩家防，回复门派速度不够的直接加血）。',
      '**紧急任务·秋风落叶**（神秘女子，图2-8）：≤5 回合内清掉对面所有小怪（神秘女子除外，一速秒 10）。杀法（适当 JQ、LH，第一回合可水清输出）：封 1 个法系杀 1 个物理 → 再封 1 个法系杀另 1 个物理 → 分配输出击杀其他（神秘女子除外）。',
      '**紧急任务·单刀直入**（守卫龙王，图2-9）：≤3 回合内击败龙宫护卫队长。其余全是物理、会破血，主死目且 ≥3 回合会跑；第 1 回合杀 BB 为主、第 2 回合杀玩家为主。杀法：封 1 个「物理」杀主（抗性低的 BB 防）→ 再封 1 个「物理」杀主（抗性低的玩家防）→ 全杀主 → 杀「封系」和 HS，其余会跑。',
      '**诅咒梦魇**(图2-10，无紧急)：所有怪残血后会跑。封「封辅」，分配输出击杀（致残血）即可。',
      '**紧急任务·邪不胜正**（被操纵的卫凝姿，图2-11）：驱逐所有妖魔鬼怪、不要伤害卫凝姿。杀法：封 1 个「法系」杀 1 个「物理」（抗性低的 BB 防）→ 封 1 个「物理」杀另 1 个「物理」→ 逐一杀其他（后期注意别群秒到主）。',
      '**紧急任务·除妖驱邪**（诅咒梦魇 BOSS，图2-12）：击败诅咒梦魇、赢得战斗胜利。均带神迹，第 3、6、9…… 回合开始时会出现「傀儡人」（数量与星级一致，即 3X 有 3 个），结束时「傀儡人」自杀使用「反间计」；后排剩下 1 个怪时、此怪会「秒 10 落叶萧萧」。杀法（适当 JQ、LH）：① 封 DT 特技杀 DT → ② 封杀 ST → ③「傀儡人」出现后、分配输出杀之 → ④ 杀主、最后杀 LG。**若无法清完「傀儡人」则须保证第 4、7、10…… 回合放出 JQ**。',
      '隐藏·秦欣鬼魂(图2-13，无紧急)：每回合会召唤 1 个「怨」，会破血；封杀主、再逐一击杀即可。',
