const ARTIFACT_TASK_GUIDES: GuideEntry[] = ARTIFACT_TASKS.map((task, index) => {
  const meta = ARTIFACT_KIND_META[task.kind]
  return {
    id: `artifact-${meta.id}-${String(index + 1).padStart(2, '0')}`,
    category: `神器·${task.kind}` as GuideCategory,
    title: `神器任务·${task.kind}：${task.name}`,
    summary: `${task.difficulty} ${task.prepare}`,
    tags: ['神器攻略', `神器任务·${task.kind}`, task.name, task.kind],
    sections: [
      {
        // 「备战准备」精简为置顶的「需要提交的物品」：只保留需上交给 NPC 的物品
        heading: '需要提交的物品',
        items: ARTIFACT_SUBMIT_ITEMS[task.name] ?? [task.prepare],
      },
      {
        heading: '领取与条件',
        items: [meta.condition],
      },
      {
        heading: '流程速记',
        items: task.route,
      },
      {
        heading: '分场战斗与机关要点（注意事项）',
        items: task.tips,
      },
      {
        heading: '日常建议',
        items: task.recommend,
      },
    ],
    images: task.images,
    source: task.source ? `${ARTIFACT_TASK_SOURCE}；${task.source}` : ARTIFACT_TASK_SOURCE,
    preset: true,
  }
})

