          "**入口**：Alt+K→活动→九色鹿·上→马上参加，确认「可正常开启」→【佛窟传送人】(丝绸之路 160,9) 传送「无名佛窟」→【涅槃圣莲】(无名佛窟 14,25) 选「开启九色鹿·上」。奖励不受双倍/精修/回梦丹影响，战斗死亡计正常损失，可中途离场再由涅槃圣莲返回。",
