          "**刷物品**走 2112（战斗最多、出物品机会最多）；**只求摇奖**走 21212『斩妖除魔』（比 2112 少 1 场、换 1 次摇奖）；**求快**走 222『神鹿有难』（仅 3 场）。下方按作者详解的 2112 路线走，其余分支跟任务追踪即可。"
