          "**④阻止魔将（维摩诘宅）**：【维摩诘】(18,9) 选项（图3-14）：`C 大展神威`→打【波旬部将】(24,11)（图3-15）——**回合数决定片段**：≤15 回合=邪魔遁逃、≥16 回合=天将魔火（刷回合数时别选出战者，以免秒掉对面）；`D 疏散百姓`→ 分别找女子/壮汉/医生打 3 场（图3-17/3-18）。",
