          "**十八罗汉成就**：需 18 个不同友方出战=十方力士(10)+善思+灵芝+青狮+5 魔将。建议每得 1 个新罗汉立即让其出战、持世留最后一场再出；另有『十方力士』（刷齐 10 位、可分次）『亦佛亦魔』（5 魔将）『前因后果』（走遍所有分支）等成就。",
